#!/usr/bin/env python3
"""Supervise bounded Boolean analysis in a separate worker; never execute model code."""
import argparse
import hashlib
import importlib.metadata
import importlib.util
import json
import math
import os
from pathlib import Path
import signal
import subprocess
import sys
import time

# Also support tools/tests that load this public script by absolute file path.
try:
    from process_supervision import run_supervised
except ModuleNotFoundError as error:
    if error.name != 'process_supervision':
        raise
    spec = importlib.util.spec_from_file_location(
        'requirements_process_supervision', Path(__file__).with_name('process_supervision.py'))
    supervision_module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(supervision_module)
    run_supervised = supervision_module.run_supervised


try:
    from memory_budget import (ResourceBudgetError, admission, enforce_address_space,
                               logic_memory_policy, observe_process_memory)
except ModuleNotFoundError as error:
    if error.name != 'memory_budget':
        raise
    spec = importlib.util.spec_from_file_location(
        'requirements_memory_budget', Path(__file__).with_name('memory_budget.py'))
    memory_module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(memory_module)
    ResourceBudgetError = memory_module.ResourceBudgetError
    admission = memory_module.admission
    enforce_address_space = memory_module.enforce_address_space
    logic_memory_policy = memory_module.logic_memory_policy
    observe_process_memory = memory_module.observe_process_memory


try:
    import activation_preflight
except ModuleNotFoundError as error:
    if error.name != 'activation_preflight':
        raise
    spec = importlib.util.spec_from_file_location(
        'requirements_activation_preflight', Path(__file__).with_name('activation_preflight.py'))
    activation_preflight = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(activation_preflight)


def artifact_identity(path):
    try:
        resolved = Path(path).resolve(strict=True)
        size = resolved.stat().st_size
        if not resolved.is_file() or size > 64 * 1024 * 1024:
            return {'status': 'UNKNOWN', 'reason': 'not a bounded regular artifact'}
        digest = hashlib.sha256()
        with resolved.open('rb') as f:
            remaining = 64 * 1024 * 1024 + 1
            while remaining:
                chunk = f.read(min(65536, remaining))
                if not chunk:
                    break
                digest.update(chunk)
                remaining -= len(chunk)
        if not remaining:
            return {'status': 'UNKNOWN', 'reason': 'artifact grew past byte limit'}
        return {'status': 'OBSERVED', 'resolved_path': str(resolved), 'sha256': digest.hexdigest()}
    except (OSError, ValueError, RuntimeError):
        return {'status': 'UNKNOWN', 'reason': 'artifact unavailable'}


def runtime_identity():
    artifact = artifact_identity(sys.executable)
    versions = {}
    for name in ['z3-solver', 'jsonschema']:
        try:
            versions[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            versions[name] = None
    return {'executable': os.path.abspath(sys.executable), 'python_version': sys.version.split()[0],
            'executable_sha256': artifact.get('sha256'), 'artifact': artifact,
            'distributions': versions, 'authentication': 'NOT_ESTABLISHED',
            'limits': 'Observed bytes/metadata in a trusted local account; not a signed runtime or dependency attestation.'}



class InputError(ValueError):
    pass


class Parser(argparse.ArgumentParser):
    def error(self, message):
        raise InputError(message)


def main(_own_cli=False):
    """Analyze with bounded children; only a fresh owned CLI limits itself."""
    started = time.monotonic()
    runtime = supervision = None
    memory = {'policy': None, 'admission': None, 'caller': None,
              'limits': [
                  'Virtual address-space limits, not RSS quotas or physical reservations.',
                  'Admission serializes cooperating calls per account; not global host enforcement.',
                  'Sequential local samples and lifetime peaks do not prove aggregate RSS.',
                  'Signals and missing diagnostics do not establish OOM.']}

    def emit(document, returncode):
        if runtime is not None:
            document['runtime'] = runtime
        if supervision is not None:
            document['supervision'] = supervision
        if memory['policy'] is not None:
            document['memory_budget'] = memory
        print(json.dumps(document, ensure_ascii=False))
        return returncode

    def exhausted():
        return {'timed_out': True, 'elapsed_seconds': 0,
                'parent_death_policy': 'WORKER_NOT_STARTED', 'cleanup_status': 'NOT_REQUIRED'}

    try:
        parser = Parser(description=__doc__)
        parser.add_argument('input', help='Bounded Boolean JSON model; not executable content')
        parser.add_argument('--timeout', type=float, default=5, help='Wall-time budget in seconds (0 < value <= 30); subject to OS scheduling')
        parser.add_argument('--table', action='store_true', help='Exact guard-activation table for up to 12 inputs, if budget permits')
        parser.add_argument('--memory-budget-mib', type=int, default=None,
                            help='Legacy budget range 256..1024 MiB; admission profile auto-caps at 512 MiB')
        args = parser.parse_args()
        if not math.isfinite(args.timeout) or not 0 < args.timeout <= 30:
            raise InputError('timeout must be greater than 0 and at most 30 seconds')
        preflight = activation_preflight.evaluate(
            Path.cwd(), args.memory_budget_mib, workload='logic',
            caller_scope='OWNED_CLI' if _own_cli else 'EXTERNAL_CALLER')
        if preflight['status'] != 'READY_FOR_LIVE_ADMISSION':
            code = preflight.get('error', {}).get('code', 'RESOURCE_HEADROOM_UNKNOWN')
            if code == 'INVALID_MEMORY_BUDGET':
                code = 'RESOURCE_POLICY_INVALID'
            raise ResourceBudgetError(code)
        effective_mib = preflight['policy']['effective_profile_mib']
        policy = logic_memory_policy(effective_mib)
        memory['activation_preflight'] = preflight
        memory['policy'] = policy
        if os.name != 'posix':
            return emit({'status': 'INCONCLUSIVE', 'error': {'code': 'SUPERVISION_UNSUPPORTED_PLATFORM',
                         'message': 'No bounded process-group supervision adapter for this platform.'}}, 2)
        runtime = runtime_identity()
        remaining = args.timeout - (time.monotonic() - started)
        if remaining <= 0:
            result = exhausted()
        else:
            caller = observe_process_memory()
            caller['sample_scope'] = caller['scope'] if 'scope' in caller else 'PROCESS_LOCAL_SAMPLES'
            caller['scope'] = 'OWNED_CLI_PROCESS' if _own_cli else 'EXTERNAL_CALLER_NOT_LIMITED'
            memory['caller'] = caller
            solver_limit = policy['roles_bytes']['solver']
            if _own_cli:
                baseline = caller.get('virtual_bytes')
                if baseline is None:
                    raise ResourceBudgetError('RESOURCE_BASELINE_UNKNOWN')
                if baseline > policy['roles_bytes']['caller']:
                    raise ResourceBudgetError('RESOURCE_BASELINE_EXCEEDS_ROLE_BUDGET')
                # Retain the larger solver ceiling for its pre-exec limit. The
                # helper rejects any attempt to raise an inherited hard limit.
                try:
                    enforce_address_space(policy['roles_bytes']['caller'], solver_limit)
                except ResourceBudgetError:
                    raise
                except (ValueError, OSError, subprocess.SubprocessError) as error:
                    raise ResourceBudgetError('RESOURCE_CONTROL_SETUP_FAILED') from error
                observed = observe_process_memory()
                observed['sample_scope'] = observed.get('scope', 'PROCESS_LOCAL_SAMPLES')
                observed['scope'] = 'OWNED_CLI_PROCESS'
                memory['caller'] = observed
            with admission(policy) as (lease_fd, admitted):
                memory['admission'] = admitted
                preflight['execution']['control_state'] = 'PARTIALLY_APPLIED'
                preflight['execution']['enforced'] = [
                    'cooperative account admission lock acquired',
                    'visible headroom >= 2x profile at live admission sample']
                remaining = args.timeout - (time.monotonic() - started)
                command = [os.path.abspath(sys.executable)]
                if sys.flags.no_site:
                    command.append('-S')
                command += ['-B', str(Path(__file__).with_name('logic_engine.py')), args.input,
                            '--timeout', str(max(.000001, remaining))]
                if args.table:
                    command.append('--table')
                # Count command setup against the same total deadline too.
                remaining = args.timeout - (time.monotonic() - started)
                if remaining <= 0:
                    result = exhausted()
                else:
                    try:
                        result = run_supervised(command, remaining, pass_fds=(lease_fd,),
                                                address_space_limit=(solver_limit, solver_limit))
                    except (ValueError, OSError, subprocess.SubprocessError) as error:
                        raise ResourceBudgetError('RESOURCE_CONTROL_SETUP_FAILED') from error
                    preflight['execution']['control_state'] = 'APPLIED'
                    preflight['execution']['enforced'].append(
                        'role-specific RLIMIT_AS applied before worker exec')
                    preflight['execution']['workers'] = 'COMPLETED'
        supervision = {'worker_elapsed_seconds': result['elapsed_seconds'], 'wall_budget_seconds': args.timeout,
                       'parent_death_policy': result['parent_death_policy'], 'cleanup_status': result['cleanup_status'],
                       'cleanup_grace_seconds': 1,
                       'limits': 'Responsive OS and live supervisor required for deadline handling; Linux death signal covers direct worker only. No arbitrary descendant or hardware isolation guarantee.'}
        if result.get('output_limit'):
            return emit({'status': 'INCONCLUSIVE', 'error': {'code': 'WORKER_OUTPUT_LIMIT', 'message': 'Worker exceeded its bounded output allowance; cleanup outcome is recorded separately.'}}, 3)
        if result['timed_out']:
            return emit({'status': 'INCONCLUSIVE', 'error': {'code': 'WALL_CLOCK_LIMIT', 'message': 'Wall-time budget exhausted; worker cleanup outcome is recorded separately.'}}, 3)
        try:
            document = json.loads(result['stdout'])
            if not isinstance(document, dict):
                raise ValueError('worker response is not an object')
            if result['returncode'] != 0 and 'error' not in document:
                raise ValueError('worker failed despite emitting a success-shaped result')
        except ValueError:
            return emit({'status': 'INCONCLUSIVE', 'error': {'code': 'WORKER_FAILED', 'message': 'Worker exited without a structured result.'},
                         'worker_returncode': result['returncode']}, 2)
        if isinstance(document.get('error'), dict) and document['error'].get('code') == 'MEMORY_BUDGET_EXCEEDED':
            # A resource failure cannot carry partial successful analysis data.
            failure = {'status': 'INCONCLUSIVE', 'error': document['error']}
            if isinstance(document.get('memory_observation'), dict):
                failure['memory_observation'] = document['memory_observation']
            return emit(failure, 3)
        if _own_cli and result['returncode'] == 0 and 'error' not in document:
            observed = document.get('memory_observation')
            if (not isinstance(observed, dict)
                    or type(observed.get('as_soft_bytes')) is not int
                    or type(observed.get('as_hard_bytes')) is not int
                    or observed['as_soft_bytes'] != solver_limit
                    or observed['as_hard_bytes'] != solver_limit):
                raise ResourceBudgetError('RESOURCE_LIMIT_NOT_OBSERVED')
        return emit(document, result['returncode'] if result['returncode'] in (0, 2, 3) else 2)
    except InputError as error:
        return emit({'error': {'code': 'INVALID_INPUT', 'message': str(error)}}, 2)
    except ResourceBudgetError as error:
        return emit({'status': 'INCONCLUSIVE', 'error': {'code': error.code, 'message': str(error)}}, 3)
    except MemoryError:
        os.write(1, b'{"status":"INCONCLUSIVE","error":{"code":"MEMORY_BUDGET_EXCEEDED"}}\n')
        return 3
    except (ValueError, OSError, subprocess.SubprocessError) as error:
        return emit({'error': {'code': 'SUPERVISOR_ERROR', 'message': str(error)}}, 2)
    except KeyboardInterrupt:
        return emit({'status': 'INCONCLUSIVE', 'error': {'code': 'INTERRUPTED', 'message': 'Analysis interrupted; cleanup was attempted under its bounded contract.'}}, 130)


if __name__ == '__main__':
    def interrupted(signum, frame):
        raise KeyboardInterrupt()
    signal.signal(signal.SIGTERM, interrupted)
    raise SystemExit(main(_own_cli=True))

"""Bounded document reads from a directory or immutable Git-bound byte records.

These sources do not isolate an interpreter from another process with the same
UID. Installed schemas remain trusted assets outside the candidate source.
"""
import hashlib
from pathlib import Path, PurePosixPath
from types import MappingProxyType

from safe_io import MAX_FILE_BYTES, read_regular


class Invalid(ValueError):
    def __init__(self, code, detail):
        self.code = code
        self.detail = detail
        super().__init__(f'{code}: {detail}')


def canonical_relative(relative, *, allow_root=False):
    """Reject alternate spellings before PurePath can normalize them away."""
    value = str(relative) if isinstance(relative, PurePosixPath) else relative
    if not isinstance(value, str):
        raise Invalid('UNSAFE_PATH', repr(relative))
    path = PurePosixPath(value)
    if (not value or '\x00' in value or '\\' in value or path.is_absolute()
            or '..' in path.parts or path.as_posix() != value
            or (value == '.' and not allow_root)):
        raise Invalid('UNSAFE_PATH', value)
    return path


def safe_file(base, relative):
    """Retain the legacy path API and symlink diagnostic for filesystem users."""
    base = Path(base)
    path = Path(relative)
    target = (base / path).resolve()
    if path.is_absolute() or not target.is_relative_to(base.resolve()):
        raise Invalid('UNSAFE_PATH', relative)
    cursor = base.resolve()
    for component in path.parts:
        cursor = cursor / component
        if cursor.is_symlink():
            raise Invalid('UNSAFE_PATH', relative)
    return base.resolve() / path


class FilesystemSource:
    def __init__(self, base):
        self.base = Path(base).resolve()

    def read(self, relative):
        path = canonical_relative(relative)
        safe_file(self.base, path)
        return read_regular(self.base, path)

    def scope(self, relative_parent):
        path = canonical_relative(relative_parent, allow_root=True)
        return FilesystemSource(safe_file(self.base, path))


class MemorySource:
    def __init__(self, mapping, blob_oids):
        records, ids = dict(mapping), dict(blob_oids)
        for name in set(records) | set(ids):
            if type(name) is not str:
                raise Invalid('UNSAFE_PATH', repr(name))
            canonical_relative(name)
        if set(records) != set(ids):
            raise Invalid('BLOB_OID_MISSING', 'Document and blob OID paths differ')
        for name, raw in records.items():
            if type(raw) is not bytes:
                raise TypeError(f'Document {name!r} must contain immutable bytes')
            if type(ids[name]) is not str:
                raise TypeError(f'Blob OID for {name!r} must be a string')
        self._records = MappingProxyType(records)
        self._blob_oids = MappingProxyType(ids)
        self._prefix = PurePosixPath('.')
        self._consumed = {}

    @property
    def consumed_files(self):
        return [dict(self._consumed[name]) for name in sorted(self._consumed)]

    def read(self, relative):
        path = canonical_relative(relative)
        name = (self._prefix / path).as_posix()
        try:
            raw = self._records[name]
        except KeyError:
            raise FileNotFoundError(name) from None
        if len(raw) > MAX_FILE_BYTES:
            raise ValueError('FILE_SIZE_LIMIT')
        actual = hashlib.sha256(b'blob ' + str(len(raw)).encode('ascii') + b'\0' + raw).hexdigest()
        if actual != self._blob_oids[name]:
            raise Invalid('BLOB_OID_MISMATCH', name)
        self._consumed[name] = {'path': name, 'git_oid': actual, 'sha256': hashlib.sha256(raw).hexdigest()}
        return raw

    def scope(self, relative_parent):
        path = canonical_relative(relative_parent, allow_root=True)
        scoped = object.__new__(MemorySource)
        scoped._records = self._records
        scoped._blob_oids = self._blob_oids
        scoped._prefix = self._prefix / path
        scoped._consumed = self._consumed
        return scoped

"""Bounded local transport for verified documentation bytes, never executable code.

Frame: 4-byte magic, 4-byte big-endian JSON header length, header, raw blobs.
No files are created. Both endpoints are installed, trusted local components.
"""
import hashlib
import json
from pathlib import PurePosixPath
import re
from json_preflight import preflight_json

MAGIC = b'RGB1'
MAX_HEADER = 2 * 1024 * 1024
MAX_FILE = 8 * 1024 * 1024
MAX_TOTAL = 32 * 1024 * 1024
MAX_ENTRIES = 4096


def canonical_path(name):
    if not isinstance(name, str) or not name or '\\' in name or '\0' in name:
        raise ValueError('UNSAFE_TREE_PATH')
    path = PurePosixPath(name)
    if path.is_absolute() or str(path) != name or any(x in ('.', '..', '.git') for x in path.parts) or len(path.parts) > 64:
        raise ValueError('UNSAFE_TREE_PATH')
    return name


def blob_oid(raw):
    return hashlib.sha256(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest()


def _metadata(header):
    if not isinstance(header, dict) or set(header) != {'version', 'prd', 'files'} or type(header['version']) is not int or header['version'] != 1:
        raise ValueError('INVALID_BUNDLE_HEADER')
    canonical_path(header['prd'])
    rows = header['files']
    if not isinstance(rows, list) or len(rows) > MAX_ENTRIES:
        raise ValueError('ENTRY_LIMIT')
    seen = set()
    total = 0
    for row in rows:
        if not isinstance(row, dict) or set(row) != {'path', 'oid', 'size'}:
            raise ValueError('INVALID_BUNDLE_HEADER')
        name = canonical_path(row['path'])
        if name in seen:
            raise ValueError('DUPLICATE_BUNDLE_PATH')
        seen.add(name)
        if not isinstance(row['oid'], str) or not re.fullmatch('[0-9a-f]{64}', row['oid']):
            raise ValueError('SHA256_REQUIRED')
        if type(row['size']) is not int or not 0 <= row['size'] <= MAX_FILE:
            raise ValueError('FILE_SIZE_LIMIT')
        total += row['size']
        if total > MAX_TOTAL:
            raise ValueError('BYTE_LIMIT')
    if header['prd'] not in seen:
        raise ValueError('PRD_MISSING')
    return rows


def encode_bundle(prd, files, oids):
    if set(files) != set(oids):
        raise ValueError('BLOB_OID_MISSING')
    rows = []
    for name in sorted(files):
        raw = files[name]
        if type(raw) is not bytes:
            raise ValueError('BUNDLE_BYTES_REQUIRED')
        rows.append({'path': name, 'oid': oids[name], 'size': len(raw)})
    header = {'version': 1, 'prd': prd, 'files': rows}
    _metadata(header)
    for name, raw in files.items():
        if blob_oid(raw) != oids[name]:
            raise ValueError('BLOB_OID_MISMATCH')
    raw_header = json.dumps(header, ensure_ascii=True, separators=(',', ':')).encode()
    if len(raw_header) > MAX_HEADER:
        raise ValueError('BUNDLE_HEADER_LIMIT')
    return b''.join([MAGIC, len(raw_header).to_bytes(4, 'big'), raw_header] + [files[row['path']] for row in rows])


def _exact(stream, size):
    chunks = []
    remaining = size
    while remaining:
        chunk = stream.read(min(65536, remaining))
        if not chunk:
            raise ValueError('TRUNCATED_BUNDLE')
        chunks.append(chunk)
        remaining -= len(chunk)
    return b''.join(chunks)


def _unique_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('DUPLICATE_BUNDLE_KEY')
        result[key] = value
    return result


def read_bundle(stream):
    if _exact(stream, 4) != MAGIC:
        raise ValueError('INVALID_BUNDLE_MAGIC')
    size = int.from_bytes(_exact(stream, 4), 'big')
    if not 0 < size <= MAX_HEADER:
        raise ValueError('BUNDLE_HEADER_LIMIT')
    raw = _exact(stream, size)
    preflight_json(raw, max_bytes=MAX_HEADER)
    header = json.loads(raw, object_pairs_hook=_unique_pairs)
    rows = _metadata(header)
    files, oids = {}, {}
    for row in rows:
        data = _exact(stream, row['size'])
        if blob_oid(data) != row['oid']:
            raise ValueError('BLOB_OID_MISMATCH')
        files[row['path']], oids[row['path']] = data, row['oid']
    if stream.read(1):
        raise ValueError('TRAILING_BUNDLE_DATA')
    return header['prd'], files, oids

"""Bound JSON structure before passing bytes to a JSON decoder.

This is deliberately not a JSON grammar or encoding validator. The caller must
still decode the input with its normal duplicate-key and constant policies.
"""


def preflight_json(raw, max_depth=96, max_bytes=262144):
    """Reject oversized or structurally unbalanced JSON bytes.

    Depth counts open objects and arrays; strings and their escapes are
    skipped. Raises ValueError on invalid limits or structural violations.
    """
    if not isinstance(raw, bytes):
        raise ValueError('raw must be bytes')
    if type(max_depth) is not int or max_depth < 1:
        raise ValueError('max_depth must be a positive integer')
    if type(max_bytes) is not int or max_bytes < 1:
        raise ValueError('max_bytes must be a positive integer')
    if len(raw) > max_bytes:
        raise ValueError('JSON exceeds maximum bytes')

    stack = []
    in_string = False
    escaped = False
    for byte in raw:
        if in_string:
            if escaped:
                escaped = False
            elif byte == 92:  # backslash
                escaped = True
            elif byte == 34:  # quote
                in_string = False
        elif byte == 34:
            in_string = True
        elif byte == 91 or byte == 123:  # [ or {
            if len(stack) >= max_depth:
                raise ValueError('JSON exceeds maximum depth')
            stack.append(byte)
        elif byte == 93 or byte == 125:  # ] or }
            expected = 91 if byte == 93 else 123
            if not stack or stack[-1] != expected:
                raise ValueError('JSON has unmatched or mismatched delimiter')
            stack.pop()
    if in_string:
        raise ValueError('JSON has an unterminated string')
    if stack:
        raise ValueError('JSON has unclosed delimiters')

#!/usr/bin/env python3
"""Analyze a bounded, explicit Boolean model; never execute model content."""
import argparse
import itertools
import hashlib
import json
import math
import os
from pathlib import Path
import re
import sys
import time

from safe_io import read_regular
from json_preflight import preflight_json
from analyze_logic import artifact_identity
from memory_budget import observe_process_memory

MEMORY_FAILURE = b'{"status":"INCONCLUSIVE","error":{"code":"MEMORY_BUDGET_EXCEEDED","message":"Worker observed an allocation failure; no model results are reported."}}\n'

MAX_BYTES = 262144
MAX_NODES = 4096
MAX_DEPTH = 32
MAX_ITEMS = 128
NAME = re.compile(r'^[A-Za-z_][A-Za-z0-9_]{0,63}$')

class InputError(ValueError):
    pass

def unique_object(pairs):
    result = {}
    for k, v in pairs:
        if k in result:
            raise InputError('duplicate JSON key: ' + k)
        result[k] = v
    return result

def keys(obj, expected):
    if type(obj) is not dict or set(obj) != set(expected):
        raise InputError('unexpected or missing fields')

def name(value):
    if type(value) is not str or not NAME.fullmatch(value):
        raise InputError('invalid name or ID')
    return value

def validate(data):
    keys(data, ('inputs', 'outputs', 'domain', 'rules', 'properties'))
    for field in ('inputs', 'outputs', 'rules', 'properties'):
        if type(data[field]) is not list or len(data[field]) > MAX_ITEMS:
            raise InputError('invalid list or list limit: ' + field)
    variables = [name(n) for n in data['inputs'] + data['outputs']]
    if len(variables) > 32 or len(set(variables)) != len(variables):
        raise InputError('variables must be unique and total at most 32')
    ins, allvars = set(data['inputs']), set(variables)
    ids, count = set(), 0
    def expr(node, allowed, depth=1):
        nonlocal count
        count += 1
        if count > MAX_NODES or depth > MAX_DEPTH:
            raise InputError('expression node or depth limit')
        if type(node) is bool:
            return
        if type(node) is not dict:
            raise InputError('expression must be boolean or AST object')
        if set(node) == {'var'}:
            if name(node['var']) not in allowed:
                raise InputError('unknown or disallowed variable')
            return
        keys(node, ('op', 'args'))
        op, args = node['op'], node['args']
        if type(op) is not str or type(args) is not list:
            raise InputError('invalid operator or arguments')
        if op not in ('and', 'or', 'not', 'implies', 'eq'):
            raise InputError('unsupported operator')
        if (op in ('not', 'implies', 'eq') and len(args) != {'not': 1, 'implies': 2, 'eq': 2}[op]) or (op in ('and', 'or') and not 2 <= len(args) <= MAX_ITEMS):
            raise InputError('invalid operator arity')
        for child in args:
            expr(child, allowed, depth + 1)
    expr(data['domain'], ins)
    for item in data['rules']:
        keys(item, ('id', 'guard', 'response'))
        ident = name(item['id'])
        if ident in ids: raise InputError('duplicate ID')
        ids.add(ident)
        expr(item['guard'], ins); expr(item['response'], allvars)
    for item in data['properties']:
        keys(item, ('id', 'expression'))
        ident = name(item['id'])
        if ident in ids: raise InputError('duplicate ID')
        ids.add(ident)
        expr(item['expression'], allvars)
    return count

def analyze(data, z3, seconds, want_table, deadline):
    nodes = validate(data)
    variables = {n: z3.Bool(n) for n in data['inputs'] + data['outputs']}
    def compile_expr(node):
        if type(node) is bool: return z3.BoolVal(node)
        if 'var' in node: return variables[node['var']]
        args = [compile_expr(x) for x in node['args']]
        return {'and': lambda: z3.And(*args), 'or': lambda: z3.Or(*args),
                'not': lambda: z3.Not(args[0]), 'implies': lambda: z3.Implies(*args),
                'eq': lambda: args[0] == args[1]}[node['op']]()
    domain = compile_expr(data['domain'])
    guards = [compile_expr(r['guard']) for r in data['rules']]
    obligations = z3.And(*[z3.Implies(g, compile_expr(r['response'])) for g, r in zip(guards, data['rules'])])
    covered = z3.Or(*guards)
    outs = [variables[n] for n in data['outputs']]
    feasible_output = z3.Exists(outs, obligations) if outs else obligations
    def check(formula, witness_names=()):
        remaining = deadline - time.monotonic()
        if remaining < .001:
            return {'status': 'UNKNOWN', 'reason': 'total time budget exhausted'}
        solver = z3.Solver()
        solver.set(timeout=max(1, min(1000, int(remaining * 1000))))
        solver.add(formula)
        answer = solver.check()
        if answer == z3.unknown:
            return {'status': 'UNKNOWN', 'reason': solver.reason_unknown()}
        result = {'status': str(answer).upper()}
        if answer == z3.sat and witness_names:
            model = solver.model()
            result['witness'] = {n: z3.is_true(model.eval(variables[n], model_completion=True)) for n in witness_names}
        return result
    inputs = data['inputs']
    queries = {'domain': check(domain, inputs), 'gap': check(z3.And(domain, z3.Not(covered)), inputs),
               'no_output': check(z3.And(domain, z3.Not(feasible_output)), inputs),
               'rule_consistency': check(z3.And(domain, obligations), list(variables))}
    validity = {'SAT': 'VALID', 'UNSAT': 'INVALID', 'UNKNOWN': 'UNKNOWN'}[queries['domain']['status']]
    props = []
    for p in data['properties']:
        counterexample = check(z3.And(domain, obligations, z3.Not(compile_expr(p['expression']))), list(variables))
        basis = queries['rule_consistency']['status']
        if basis == 'UNSAT': consequence = 'VACUOUS'
        elif basis == 'UNKNOWN' or counterexample['status'] == 'UNKNOWN': consequence = 'UNKNOWN'
        elif counterexample['status'] == 'SAT': consequence = 'NOT_ENTAILED'
        else: consequence = 'ENTAILED'
        props.append({'id': p['id'], 'interpretation': 'Consequence of model rules within domain; not implementation verification.',
                      'consequence': consequence, 'counterexample': counterexample})
    result = {'domain_validity': validity, 'queries': queries, 'properties': props,
              'limits': {'variables': len(variables), 'ast_nodes': nodes, 'max_variables': 32, 'max_ast_nodes': MAX_NODES,
                         'max_depth': MAX_DEPTH, 'max_input_bytes': MAX_BYTES, 'total_seconds': seconds, 'per_query_seconds': 1},
              'scope': 'Results concern the supplied Boolean model only; they do not verify implementation, hardware, or human meaning.'}
    if want_table:
        if len(inputs) > 12:
            result['table'] = {'status': 'NOT_RUN', 'reason': 'more than 12 inputs'}
        else:
            table = {'status': 'EXACT', 'possible_rows': 2 ** len(inputs), 'rows_examined': 0,
                     'feasible_inputs': 0, 'covered_inputs': 0, 'inputs_without_output': 0}
            for bits in itertools.product((False, True), repeat=len(inputs)):
                fixed = z3.And(*[variables[n] == b for n, b in zip(inputs, bits)])
                d = check(z3.And(domain, fixed))
                if d['status'] == 'UNKNOWN': table['status'] = 'INCOMPLETE'; break
                if d['status'] == 'SAT':
                    c = check(z3.And(domain, fixed, covered))
                    n = check(z3.And(domain, fixed, z3.Not(feasible_output)))
                    if 'UNKNOWN' in (c['status'], n['status']): table['status'] = 'INCOMPLETE'; break
                    table['feasible_inputs'] += 1
                    table['covered_inputs'] += c['status'] == 'SAT'
                    table['inputs_without_output'] += n['status'] == 'SAT'
                table['rows_examined'] += 1
            if table['status'] == 'EXACT' and table['feasible_inputs']:
                table['coverage'] = {'metric': 'GUARD_ACTIVATION_COVERAGE', 'numerator': table['covered_inputs'], 'denominator': table['feasible_inputs']}
            result['table'] = table
    return result

class Parser(argparse.ArgumentParser):
    def error(self, message): raise InputError(message)

def main():
    try:
        parser = Parser(description=__doc__)
        parser.add_argument('input'); parser.add_argument('--timeout', type=float, default=5.0)
        parser.add_argument('--table', action='store_true')
        args = parser.parse_args()
        if not math.isfinite(args.timeout) or not 0 < args.timeout <= 30:
            raise InputError('timeout must be greater than 0 and at most 30 seconds')
        started = time.monotonic()
        deadline = started + args.timeout
        path = Path(args.input).absolute()
        raw = read_regular(path.parent, path.name, MAX_BYTES)
        preflight_json(raw, max_bytes=MAX_BYTES)
        data = json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                          parse_constant=lambda _: (_ for _ in ()).throw(InputError('non-finite JSON number')))
        validate(data)
        try:
            import z3
        except ImportError:
            print(json.dumps({'error': {'code': 'SOLVER_UNAVAILABLE', 'message': 'z3-solver is unavailable'}}))
            return 2
        try:
            result = analyze(data, z3, args.timeout, args.table, deadline)
            result['provenance'] = {'model_sha256': hashlib.sha256(raw).hexdigest(),
                                    'z3_version': z3.get_version_string(),
                                    'z3_module': artifact_identity(z3.__file__),
                                    'elapsed_seconds': time.monotonic() - started,
                                    'note': 'Hash identifies supplied bytes; it does not establish semantic correctness.'}
        except z3.Z3Exception as exc:
            print(json.dumps({'error': {'code': 'SOLVER_ERROR', 'message': str(exc)}}))
            return 2
        result['memory_observation'] = observe_process_memory()
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except MemoryError:
        os.write(1, MEMORY_FAILURE)
        return 3
    except (InputError, ValueError, OSError, UnicodeError, RecursionError) as exc:
        print(json.dumps({'error': {'code': 'INVALID_INPUT', 'message': str(exc)}}))
        return 2

if __name__ == '__main__':
    sys.exit(main())

"""Provisional engineering budgets, Linux virtual limits and cooperative admission.

RLIMIT_AS limits a process's virtual address space, not its RSS. Call the mutating
helper only in a dedicated child or an explicitly owned fresh CLI. Ordinary API
callers must leave their own process limits unchanged. Admission is same-account
cooperation, not isolation from same-UID/noncooperating code or a physical reserve.
"""
from contextlib import contextmanager
import importlib.util
import os
from pathlib import Path
import stat
import sys

try:
    import fcntl
    import resource
except ImportError:
    fcntl = resource = None

try:
    import probe_environment
except ModuleNotFoundError as error:
    if error.name != 'probe_environment':
        raise
    spec = importlib.util.spec_from_file_location(
        'requirements_probe_environment', Path(__file__).with_name('probe_environment.py'))
    probe_environment = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(probe_environment)
read_small = probe_environment.read_small

MIB = 1024 * 1024


class ResourceBudgetError(ValueError):
    def __init__(self, code):
        self.code = code
        super().__init__(code)


def memory_policy(total_mib=512):
    """Return a configurable profile, not measured hardware capacity."""
    if type(total_mib) is not int or not 256 <= total_mib <= 1024 or total_mib % 8:
        raise ResourceBudgetError('RESOURCE_POLICY_INVALID')
    unit = total_mib // 8
    roles = {'caller': unit, 'coordinator': unit * 4, 'consumer': unit * 2, 'git': unit}
    return {'total_mib': total_mib, 'total_bytes': total_mib * MIB,
            'roles_mib': roles, 'roles_bytes': {key: value * MIB for key, value in roles.items()},
            'kind': 'PROVISIONAL_ENGINEERING_POLICY', 'hardware_capacity_calibrated': False,
            'aggregate_kernel_quota': False}


def logic_memory_policy(total_mib=512):
    """Return the provisional Boolean-analysis virtual-address-space profile."""
    if type(total_mib) is not int or not 256 <= total_mib <= 1024 or total_mib % 8:
        raise ResourceBudgetError('RESOURCE_POLICY_INVALID')
    unit = total_mib // 8
    roles = {'caller': unit, 'solver': unit * 7}
    return {'total_mib': total_mib, 'total_bytes': total_mib * MIB,
            'roles_mib': roles, 'roles_bytes': {key: value * MIB for key, value in roles.items()},
            'kind': 'PROVISIONAL_ENGINEERING_POLICY', 'hardware_capacity_calibrated': False,
            'aggregate_kernel_quota': False, 'workload': 'BOOLEAN_ANALYSIS'}


def _matches_policy(value, canonical):
    """Compare canonical shapes and exact types, without numeric coercion."""
    if type(value) is not type(canonical):
        return False
    if type(canonical) is dict:
        return (all(type(key) is str for key in value)
                and value.keys() == canonical.keys()
                and all(_matches_policy(value[key], expected) for key, expected in canonical.items()))
    return value == canonical


def _canonical_policy(policy):
    """Validate a supported profile and return a fresh authoritative snapshot."""
    if type(policy) is not dict:
        raise ResourceBudgetError('RESOURCE_POLICY_INVALID')
    factory = logic_memory_policy if policy.get('workload') == 'BOOLEAN_ANALYSIS' else memory_policy
    canonical = factory(policy.get('total_mib'))
    if not _matches_policy(policy, canonical):
        raise ResourceBudgetError('RESOURCE_POLICY_INVALID')
    return canonical


def _require_linux():
    if not sys.platform.startswith('linux') or resource is None or fcntl is None or not hasattr(resource, 'RLIMIT_AS'):
        raise ResourceBudgetError('RESOURCE_CONTROL_UNSUPPORTED')


def enforce_address_space(soft_bytes, hard_bytes=None):
    """Set this process's RLIMIT_AS explicitly; return actual (soft, hard).

    Omitted hard limit preserves the inherited hard limit, so a fresh CLI can
    retain room to exec its larger coordinator. No inherited hard limit is raised.
    This function never finds or alters another process.
    """
    _require_linux()
    try:
        inherited = resource.getrlimit(resource.RLIMIT_AS)[1]
    except (OSError, ValueError) as error:
        raise ResourceBudgetError('RESOURCE_LIMIT_FAILED') from error
    selected_hard = inherited if hard_bytes is None else hard_bytes
    if (type(soft_bytes) is not int or soft_bytes <= 0
            or (hard_bytes is not None and (type(hard_bytes) is not int or hard_bytes <= 0))
            or (selected_hard != resource.RLIM_INFINITY and soft_bytes > selected_hard)
            or (inherited != resource.RLIM_INFINITY
                and (selected_hard == resource.RLIM_INFINITY or selected_hard > inherited))):
        raise ResourceBudgetError('RESOURCE_LIMIT_INVALID')
    try:
        resource.setrlimit(resource.RLIMIT_AS, (soft_bytes, selected_hard))
        return resource.getrlimit(resource.RLIMIT_AS)
    except (OSError, ValueError, OverflowError) as error:
        raise ResourceBudgetError('RESOURCE_LIMIT_FAILED') from error


def preexec_limit(soft_bytes, hard_bytes=None):
    """Closure for an explicitly selected child; avoid preexec_fn in threads."""
    return lambda: enforce_address_space(soft_bytes, hard_bytes)


def observe_process_memory():
    """Observe current virtual/RSS pages, Linux lifetime high-water RSS and limits."""
    result = {'scope': 'PROCESS_LOCAL_SAMPLES', 'virtual_bytes': None, 'rss_bytes': None,
              'peak_rss_bytes': None, 'peak_rss_scope': 'PROCESS_LIFETIME_HIGH_WATER',
              'as_soft_bytes': None, 'as_hard_bytes': None, 'rss_quota_enforced': False,
              'source': '/proc/self/statm, getrusage(RUSAGE_SELF), getrlimit(RLIMIT_AS)',
              'sampling': 'SEQUENTIAL_NOT_ATOMIC', 'status': 'UNKNOWN'}
    if not sys.platform.startswith('linux') or resource is None:
        return result
    try:
        raw = read_small('/proc/self/statm')
        pages = (raw or '').split()
        virtual, resident = int(pages[0]), int(pages[1])
        page_size = os.sysconf('SC_PAGE_SIZE')
        if virtual >= 0 and resident >= 0 and page_size > 0:
            result.update(virtual_bytes=virtual * page_size, rss_bytes=resident * page_size)
    except (OSError, ValueError, IndexError):
        pass
    try:
        result['peak_rss_bytes'] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * 1024
        soft, hard = resource.getrlimit(resource.RLIMIT_AS)
        result['as_soft_bytes'] = None if soft == resource.RLIM_INFINITY else soft
        result['as_hard_bytes'] = None if hard == resource.RLIM_INFINITY else hard
        result['as_unlimited'] = {'soft': soft == resource.RLIM_INFINITY, 'hard': hard == resource.RLIM_INFINITY}
    except (OSError, ValueError):
        pass
    if result['virtual_bytes'] is not None:
        result['status'] = 'OBSERVED_PROCESS_LOCAL'
    return result


def _admission_directory():
    return Path('/tmp') / ('requirements-admission-' + str(os.getuid()))


def _visible_headroom():
    memory = probe_environment.memory_observation()
    cgroup = probe_environment.cgroup_observation()
    available = memory.get('available_bytes')
    states = cgroup.get('limit_states', [])
    rows = cgroup.get('memory_limits', [])
    if (memory.get('status') != 'OBSERVED' or type(available) is not int or available < 0
            or cgroup.get('status') != 'OBSERVED_VISIBLE_SCOPE' or not states
            or any(row.get('memory') not in ('FINITE', 'UNLIMITED_VISIBLE_SCOPE') for row in states)
            or sum(row.get('memory') == 'FINITE' for row in states) != len(rows)):
        raise ResourceBudgetError('RESOURCE_HEADROOM_UNKNOWN')
    candidates = [available]
    for row in rows:
        limit, current = row.get('limit_bytes'), row.get('current_bytes')
        if type(limit) is not int or type(current) is not int or limit < 0 or current < 0:
            raise ResourceBudgetError('RESOURCE_HEADROOM_UNKNOWN')
        candidates.append(max(0, limit - current))
    return min(candidates), memory, cgroup


@contextmanager
def admission(policy):
    """Hold one account's nonblocking lease; yield (fd, observation).

    Pass fd explicitly with subprocess pass_fds to every consumer, and wait for
    consumers before leaving this context. Descriptors stay non-inheritable in
    the parent. Closing, rather than LOCK_UN, preserves a child's inherited lock
    if its parent dies. No glob, deletion, GC, cgroup mutation, large allocation
    or physical memory reservation.
    """
    _require_linux()
    canonical = _canonical_policy(policy)
    directory = _admission_directory()
    directory_fd = lock_fd = None
    try:
        try:
            directory.mkdir(mode=0o700, exist_ok=True)
            named = directory.lstat()
            directory_fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC)
            info = os.fstat(directory_fd)
            if (not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid()
                    or stat.S_IMODE(info.st_mode) != 0o700
                    or (named.st_dev, named.st_ino) != (info.st_dev, info.st_ino)):
                raise ResourceBudgetError('RESOURCE_ADMISSION_UNSAFE')
            lock_fd = os.open('active.lock', os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC,
                              0o600, dir_fd=directory_fd)
            info = os.fstat(lock_fd)
            if (not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_nlink != 1
                    or stat.S_IMODE(info.st_mode) != 0o600):
                raise ResourceBudgetError('RESOURCE_ADMISSION_UNSAFE')
        except OSError as error:
            raise ResourceBudgetError('RESOURCE_ADMISSION_UNSAFE') from error
        try:
            fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            raise ResourceBudgetError('RESOURCE_BUSY') from error
        headroom, memory, cgroup = _visible_headroom()
        required = 2 * canonical['total_bytes']
        if headroom < required:
            raise ResourceBudgetError('RESOURCE_HEADROOM_INSUFFICIENT')
        yield lock_fd, {'status': 'ADMITTED_COOPERATIVE', 'headroom_observed_bytes': headroom,
                        'required_headroom_bytes': required, 'scope': 'VISIBLE_KERNEL_AND_CGROUP_PARTIAL',
                        'physical_reservation': False, 'sampling': 'SEQUENTIAL_NOT_ATOMIC',
                        'memory_observation': memory, 'cgroup_observation': cgroup}
    finally:
        if lock_fd is not None:
            os.close(lock_fd)
        if directory_fd is not None:
            os.close(directory_fd)

#!/usr/bin/env python3
"""Bounded local observations only; no calibration, identifiers or target inference."""
import argparse
from datetime import datetime, timezone
import json
import os
from pathlib import Path
import platform
import shutil
import sys
import time


def read_small(path):
    try:
        with Path(path).open('r', encoding='utf-8') as f:
            value = f.read(16385)
        return value if len(value) <= 16384 else None
    except (OSError, UnicodeError):
        return None


def memory_observation():
    raw = read_small('/proc/meminfo') if sys.platform.startswith('linux') else None
    values = {}
    for line in (raw or '').splitlines():
        key, _, rest = line.partition(':')
        parts = rest.split()
        if key in ['MemTotal', 'MemAvailable', 'SwapTotal', 'SwapFree'] and len(parts) == 2 and parts[1] == 'kB':
            try:
                number = int(parts[0])
                if number >= 0:
                    values[key] = number * 1024
            except ValueError:
                pass
    return {'status': 'OBSERVED' if 'MemAvailable' in values else 'UNKNOWN',
            'source': '/proc/meminfo (visible kernel scope)' if raw else 'UNAVAILABLE',
            'total_bytes': values.get('MemTotal'), 'available_bytes': values.get('MemAvailable'),
            'swap_total_bytes': values.get('SwapTotal'), 'swap_free_bytes': values.get('SwapFree')}


def cgroup_observation():
    """Observe visible cgroup-v2 ancestors, not invisible host limits."""
    source = '/proc/self/cgroup and visible /sys/fs/cgroup ancestors'
    raw = read_small('/proc/self/cgroup')
    candidates = [line[3:] for line in (raw or '').splitlines() if line.startswith('0::')]
    unknown = {'status': 'UNKNOWN', 'source': source, 'memory_limits': [], 'cpu_quotas': [], 'limit_states': [],
               'limitation': 'No safe visible cgroup-v2 path; host limits not inferred.'}
    if len(candidates) != 1:
        return unknown
    relative = Path(candidates[0].lstrip('/'))
    if '..' in relative.parts or len(relative.parts) > 64:
        return unknown
    root = Path('/sys/fs/cgroup')
    current = root / relative
    if not current.is_dir():
        return unknown
    memory = []; cpu = []; states = []; observed = False
    for _ in range(65):
        limit = read_small(current / 'memory.max')
        usage = read_small(current / 'memory.current')
        quota = read_small(current / 'cpu.max')
        observed |= any(x is not None for x in [limit, usage, quota])
        state = {'visible_ancestor': len(states), 'memory': 'UNKNOWN', 'cpu': 'UNKNOWN'}
        if limit is not None:
            if limit.strip() == 'max':
                state['memory'] = 'UNLIMITED_VISIBLE_SCOPE'
            else:
                try:
                    state['memory'] = 'FINITE' if int(limit) >= 0 else 'MALFORMED'
                except ValueError:
                    state['memory'] = 'MALFORMED'
        if quota is not None:
            parts = quota.split()
            if len(parts) == 2:
                try:
                    period = int(parts[1])
                    if period <= 0:
                        raise ValueError()
                    if parts[0] == 'max':
                        state['cpu'] = 'UNLIMITED_VISIBLE_SCOPE'
                    else:
                        state['cpu'] = 'FINITE' if int(parts[0]) > 0 else 'MALFORMED'
                except ValueError:
                    state['cpu'] = 'MALFORMED'
            else:
                state['cpu'] = 'MALFORMED'
        states.append(state)
        if limit and limit.strip() != 'max':
            try:
                n = int(limit)
                u = int(usage) if usage is not None else None
                if n >= 0 and (u is None or u >= 0):
                    memory.append({'limit_bytes': n, 'current_bytes': u,
                                   'sampled_headroom_bytes': max(0, n-u) if u is not None else None})
            except ValueError:
                pass
        if quota:
            parts = quota.split()
            if len(parts) == 2 and parts[0] != 'max':
                try:
                    q, p = map(int, parts)
                    if q > 0 and p > 0:
                        cpu.append({'quota': q, 'period': p, 'cpu_time_ratio': q/p})
                except ValueError:
                    pass
        if current == root:
            break
        current = current.parent
    return {'status': 'OBSERVED_VISIBLE_SCOPE' if observed else 'UNKNOWN', 'source': source,
            'memory_limits': memory, 'cpu_quotas': cpu, 'limit_states': states,
            'limitation': 'Sequential samples; hidden ancestors/host and concurrent changes remain unknown.'}


def cpu_model_observation():
    if not sys.platform.startswith('linux'):
        return {'status': 'UNKNOWN', 'model': None, 'class': 'UNKNOWN', 'source': 'OS adapter unavailable'}
    try:
        with Path('/proc/cpuinfo').open('r', encoding='utf-8') as stream:
            raw = stream.read(16384)
    except (OSError, UnicodeError):
        raw = None
    for line in (raw or '').splitlines():
        key, _, value = line.partition(':')
        if key.strip().lower() in ('model name', 'hardware') and value.strip():
            model = value.strip()[:160]
            return {'status': 'OBSERVED', 'model': model, 'class': 'MODEL_STRING_ONLY',
                    'source': '/proc/cpuinfo (bounded first matching field)'}
    return {'status': 'UNKNOWN', 'model': None, 'class': 'UNKNOWN', 'source': '/proc/cpuinfo unavailable or field absent'}


def probe(path):
    start = time.monotonic()
    memory = memory_observation()
    cgroup = cgroup_observation() if sys.platform.startswith('linux') else {
        'status': 'UNSUPPORTED_ADAPTER', 'source': 'cgroup-v2 Linux only', 'memory_limits': [], 'cpu_quotas': [], 'limit_states': []}
    try:
        affinity = len(os.sched_getaffinity(0))
    except (AttributeError, OSError):
        affinity = None
    release = platform.release()
    indicators = []
    if 'microsoft' in release.lower():
        indicators.append('WSL_KERNEL_INDICATOR')
    if Path('/.dockerenv').is_file():
        indicators.append('CONTAINER_FILE_INDICATOR')
    try:
        usage = shutil.disk_usage(path)
        storage = {'status': 'OBSERVED', 'source': 'disk_usage of requested path',
                   'total_bytes': usage.total, 'free_bytes': usage.free}
    except (OSError, ValueError):
        storage = {'status': 'UNKNOWN', 'source': 'requested path unavailable', 'total_bytes': None, 'free_bytes': None}
    candidates = [memory['available_bytes']] if memory['available_bytes'] is not None else []
    candidates.extend(x['sampled_headroom_bytes'] for x in cgroup['memory_limits'] if x['sampled_headroom_bytes'] is not None)
    return {'schema_version': '1.0.0', 'kind': 'OBSERVED_LOCAL_ENVIRONMENT',
            'observed_at': datetime.now(timezone.utc).isoformat(), 'elapsed_seconds': time.monotonic()-start,
            'platform': {'os': sys.platform, 'architecture': platform.machine(), 'kernel_release': release,
                         'python': platform.python_version()},
            'hosting': {'status': 'INDICATORS_ONLY' if indicators else 'UNKNOWN', 'indicators': indicators},
            'cpu': {'source': 'os.cpu_count / sched_getaffinity / visible cgroup CPU quotas',
                    'logical_visible': os.cpu_count(), 'affinity_count': affinity,
                    'effective_exclusive_cpu_capacity': None, 'model': cpu_model_observation()},
            'memory': memory, 'cgroup': cgroup,
            'sampled_memory_headroom': {'status': 'PARTIAL_ESTIMATE' if candidates else 'UNKNOWN',
                                       'bytes': min(candidates) if candidates else None,
                                       'not_a_budget': True},
            'storage': storage, 'thermal': {'status': 'NOT_MEASURED'},
            'capacity_estimate': {'status': 'NOT_CALIBRATED'},
            'coverage': {'status': 'NOT_COMPUTED_FROM_HARDWARE', 'percent': None},
            'execution_authorized': False, 'target_equivalence': 'NOT_ESTABLISHED',
            'observation_scope': {'visible_runtime': 'OBSERVED', 'physical_host': 'NOT_OBSERVED'},
            'resource_admission': 'NOT_ASSESSED',
            'limits': ['Local visible scope only; no hardware identity or throughput claim.',
                       'No benchmark, temperature sampling, network request or configuration mutation.',
                       'Non-Linux memory/quota adapters are not implemented; unavailable fields remain UNKNOWN.',
                       'Samples are not atomic; do not use them as enforceable resource limits.']}


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--path', type=Path, default=Path.cwd(), help='Existing storage path to observe; no writes')
    args = p.parse_args()
    from analyze_logic import runtime_identity
    document = probe(args.path)
    document['runtime'] = runtime_identity()
    print(json.dumps(document, ensure_ascii=False, allow_nan=False))
    return 0

if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Linux-only bounded tree observation. Integrity evidence is not READY authority."""
import argparse
import contextlib
import ctypes
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import stat
import struct
import subprocess
import sys
import tempfile
import time

class GuardError(ValueError):
    pass

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=True, separators=(',', ':')).encode()

def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()

class Observation:
    """Reject all relevant events, including overflow, watch loss and unmount.

    No historical coverage; local Linux filesystem only; trusted kernel/user.
    All existing directories are armed before the content-read window begins.
    Preparation itself is not claimed as covered. New directories cause rejection, not silent
    recursive resubscription. Reads do not trigger the chosen mask.
    """
    MASK = 0x2 | 0x4 | 0x8 | 0x40 | 0x80 | 0x100 | 0x200 | 0x400 | 0x800 | 0x2000
    def __enter__(self):
        self.lib = ctypes.CDLL(None, use_errno=True)
        self.fd = self.lib.inotify_init1(os.O_NONBLOCK | os.O_CLOEXEC)
        if self.fd < 0:
            raise GuardError('MONITOR_UNAVAILABLE')
        return self

    def add(self, path):
        # IN_ONLYDIR | IN_DONT_FOLLOW; watches pin directory inodes.
        if self.lib.inotify_add_watch(self.fd, os.fsencode(path), self.MASK | 0x1000000 | 0x2000000) < 0:
            raise GuardError('WATCH_UNAVAILABLE')

    def arm(self, root):
        # Two phases: register the whole existing hierarchy, then begin reading
        # contents. Ancestor watches reject topology changes during preparation.
        pending = [root]
        count = 0
        while pending:
            path = pending.pop()
            if len(path.relative_to(root).parts) > 64:
                raise GuardError('DEPTH_LIMIT')
            self.add(path)
            count += 1
            if count > 4096:
                raise GuardError('WATCH_DIRECTORY_LIMIT')
            for child in sorted(path.iterdir(), key=lambda p: p.name):
                if stat.S_ISDIR(child.lstat().st_mode):
                    pending.append(child)
            self.check()
        self.check()
        return time.time_ns()

    def check(self):
        try:
            data = os.read(self.fd, 65536)
        except BlockingIOError:
            return
        events = []
        at = 0
        while at < len(data):
            wd, mask, cookie, size = struct.unpack_from('iIII', data, at)
            events.append({'watch': wd, 'mask': mask})
            at += 16 + size
        if events:
            raise GuardError('OBSERVED_CHANGE_OR_MONITOR_LOSS:' + json.dumps(events))

    def __exit__(self, *args):
        os.close(self.fd)

@contextlib.contextmanager
def lock(root, timeout):
    """Exclusive cooperative lock outside the observed tree, bounded wait."""
    if not math.isfinite(timeout) or not 0 < timeout <= 300:
        raise GuardError('INVALID_TIMEOUT')
    directory = Path(tempfile.gettempdir()) / ('requirements-guard-' + str(os.getuid()))
    directory.mkdir(mode=0o700, exist_ok=True)
    info = directory.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o077:
        raise GuardError('UNSAFE_LOCK_DIRECTORY')
    fd = os.open(directory / (digest(str(root)) + '.lock'), os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_nlink != 1:
            raise GuardError('UNSAFE_LOCK_FILE')
        deadline = time.monotonic() + timeout
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= deadline:
                    raise GuardError('LOCK_TIMEOUT')
                time.sleep(min(.01, max(0, deadline - time.monotonic())))
        yield
    finally:
        os.close(fd)

def tree(root, observer, destination=None, max_bytes=32 * 1024 * 1024, max_entries=4096):
    """Full directory inventory. No symlinks/special files. Stream bounded files.

    Flat canonical leaves commit the entire hierarchy (paths, kinds, modes,
    sizes and content SHA-256), including empty directories. This is a full-tree
    commitment, not Git's tree format or an incremental Merkle implementation.
    """
    leaves = []
    total = 0
    def walk(path, relative):
        nonlocal total
        if len(relative.parts) > 64:
            raise GuardError('DEPTH_LIMIT')
        info = path.lstat()
        if len(leaves) >= max_entries:
            raise GuardError('ENTRY_LIMIT')
        row = {'path': relative.as_posix(), 'mode': stat.S_IMODE(info.st_mode)}
        if stat.S_ISDIR(info.st_mode):
            observer.add(path)
            row['kind'] = 'directory'
            leaves.append(row)
            if destination is not None:
                (destination / relative).mkdir(parents=True, exist_ok=True)
            for child in sorted(path.iterdir(), key=lambda p: p.name):
                walk(child, relative / child.name)
        elif stat.S_ISREG(info.st_mode):
            row['kind'] = 'file'
            fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_CLOEXEC | os.O_NONBLOCK)
            output = None
            try:
                current = os.fstat(fd)
                if not stat.S_ISREG(current.st_mode) or (info.st_dev, info.st_ino) != (current.st_dev, current.st_ino):
                    raise GuardError('FILE_REPLACED')
                if destination is not None:
                    output = (destination / relative).open('xb')
                hashed = hashlib.sha256()
                size = 0
                while True:
                    raw = os.read(fd, 65536)
                    if not raw:
                        break
                    total += len(raw)
                    size += len(raw)
                    if total > max_bytes:
                        raise GuardError('BYTE_LIMIT')
                    hashed.update(raw)
                    if output is not None:
                        output.write(raw)
                row.update(size=size, sha256=hashed.hexdigest())
                leaves.append(row)
            finally:
                os.close(fd)
                if output is not None:
                    output.close()
        else:
            raise GuardError('UNSUPPORTED_ENTRY:' + row['path'])
        observer.check()
    walk(root, Path('.'))
    observer.check()
    return {'format': 'full-tree-sha256/v1', 'tree_sha256': digest(leaves), 'entries': leaves, 'bytes': total}

def observe(root, baseline=None, prd=None, timeout=15):
    if root.is_symlink():
        raise GuardError('ROOT_SYMLINK')
    root = root.resolve(strict=True)
    if not root.is_dir():
        raise GuardError('ROOT_NOT_DIRECTORY')
    with lock(root, timeout), Observation() as monitor, tempfile.TemporaryDirectory(prefix='requirements-snapshot-') as td:
        # Parent changes (even unrelated siblings) conservatively invalidate.
        monitor.add(root.parent)
        armed_at = monitor.arm(root)
        snapshot = Path(td) / 'bundle'
        manifest = tree(root, monitor, snapshot if prd is not None else None)
        if baseline is not None:
            if not isinstance(baseline, dict) or not isinstance(baseline.get('entries'), list) or baseline.get('format') != manifest['format'] or baseline.get('tree_sha256') != digest(baseline.get('entries')):
                raise GuardError('INVALID_BASELINE')
            if manifest['entries'] != baseline['entries']:
                raise GuardError('TREE_CHANGED')
        validation = None
        if prd is not None:
            relative = Path(prd)
            if relative.is_absolute() or '..' in relative.parts or relative == Path('.'):
                raise GuardError('UNSAFE_PRD_PATH')
            script = Path(__file__).with_name('validate_prd.py')
            result = subprocess.run([sys.executable, '-B', str(script), str(snapshot / relative)], capture_output=True, text=True, timeout=timeout)
            if result.returncode:
                raise GuardError('DOCUMENT_INVALID:' + result.stdout + result.stderr)
            validation = json.loads(result.stdout)
        monitor.check()
        manifest.update(status='OBSERVED_SNAPSHOT', document_validation=validation,
                        armed_at_unix_ns=armed_at, final_check_unix_ns=time.time_ns(),
                        limits=['Coverage only after all watches are armed through final check; preparation, past and future excluded.',
                                'Linux local filesystem, trusted validator/kernel/account; no hostile same-UID guarantee.',
                                'Cooperative lock only; no cryptographic proof of RDD or downstream enforcement.'])
        return manifest

def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('action', choices=['snapshot', 'verify', 'validate', 'advance'])
    p.add_argument('root', type=Path)
    p.add_argument('--baseline', type=Path)
    p.add_argument('--prd')
    p.add_argument('--timeout', type=float, default=15)
    args = p.parse_args()
    try:
        if args.action == 'verify' and args.baseline is None:
            raise GuardError('BASELINE_REQUIRED')
        if args.action in ['validate', 'advance'] and not args.prd:
            raise GuardError('PRD_REQUIRED')
        baseline = json.loads(args.baseline.read_text()) if args.baseline else None
        if args.baseline is not None and not isinstance(baseline, dict):
            raise GuardError('INVALID_BASELINE')
        report = observe(args.root, baseline, args.prd, args.timeout)
        if args.action == 'advance':
            # Never infer an actual configured consumer, protected CI or authentic
            # native receipt from a self-declared JSON field or a successful check.
            raise GuardError('DOWNSTREAM_NOT_CONFIGURED: advancement blocked; snapshot validation is not READY authority')
        print(json.dumps(report, ensure_ascii=True))
        return 0
    except (GuardError, OSError, ValueError, subprocess.TimeoutExpired) as err:
        print(json.dumps({'status': 'BLOCKED', 'error': str(err)}))
        return 1

if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Read-only validation of interrogation records; never infers human intent."""
import argparse
from safe_io import read_regular
from document_source import FilesystemSource, Invalid, safe_file
import hashlib
import json
from pathlib import Path
from jsonschema import Draft202012Validator

ROOT = Path(__file__).resolve().parents[1]

def need(condition, code, detail):
    if not condition:
        raise Invalid(code, detail)

def structural(data, filename):
    schema = json.loads(read_regular(ROOT / 'assets', filename).decode('utf-8'))
    errors = sorted(Draft202012Validator(schema).iter_errors(data), key=lambda e: str(list(e.path)))
    need(not errors, 'SCHEMA', str(errors[0]) if errors else '')

def unique(items, key='id'):
    ids = [item[key] for item in items]
    need(len(ids) == len(set(ids)), 'DUPLICATE_ID', ids)

def _receipt_bytes(source, relative, missing_code, detail):
    try:
        return source.read(relative)
    except (FileNotFoundError, NotADirectoryError, IsADirectoryError):
        raise Invalid(missing_code, detail) from None
    except ValueError as err:
        if str(err) == 'NOT_REGULAR_FILE':
            raise Invalid(missing_code, detail) from None
        raise

def receipt(base, entry, expected, source=None):
    source = source if source is not None else FilesystemSource(base)
    raw = _receipt_bytes(source, entry['path'], 'RECEIPT_MISSING', entry['path'])
    text = raw.decode('utf-8') if entry['format'] == 'PLAIN_TEXT' else json.loads(raw)['question']
    need(hashlib.sha256(raw).hexdigest() == entry['sha256'] and text == expected, 'RECEIPT_MISMATCH', entry['path'])

def validate(doc, base=None, source=None):
    if source is None and base is not None:
        source = FilesystemSource(base)
    structural(doc, 'interview.schema.json')
    questions = [e['question'] for e in doc['exchanges']]
    answers = [e['answer'] for e in doc['exchanges'] if e['answer'] is not None]
    for collection in [doc['actors'], doc['sources'], doc['topics'], questions, answers, doc['research']]:
        unique(collection)
    all_ids = [item['id'] for collection in [doc['actors'], doc['sources'], doc['topics'], questions, answers, doc['research']] for item in collection]
    need(len(all_ids) == len(set(all_ids)), 'DUPLICATE_ID', 'IDs collide between collections')
    actors = {a['id']: a for a in doc['actors']}
    sources = {s['id']: s for s in doc['sources']}
    topics = {t['id']: t for t in doc['topics']}
    question_index = {q['id']: i for i, q in enumerate(questions)}
    closed = doc['status'] == 'COMPLETE'
    def source_refs(ids):
        need(set(ids) <= set(sources), 'DANGLING_REFERENCE', sorted(set(ids) - set(sources)))
    if doc['mode'] == 'INDEPENDENT_ASSISTANT_INTERVIEW':
        interrogators = [a for a in doc['actors'] if a['role'] == 'INTERROGATOR']
        responders = [a for a in doc['actors'] if a['role'] == 'ASSISTANT_RESPONDER']
        need(len(interrogators) == 1 and len(responders) == 1, 'INDEPENDENCE_MISSING', 'Two distinct roles required')
        i, r = interrogators[0], responders[0]
        need(i['runtime_refs'] and r['runtime_refs'] and not set(i['runtime_refs']) & set(r['runtime_refs']), 'INDEPENDENCE_MISSING', 'Runtime references missing or shared')
    pending = []
    for i, exchange in enumerate(doc['exchanges']):
        q, a, assessment = exchange['question'], exchange['answer'], exchange['assessment']
        need(q['by_actor'] in actors and q['to_actor'] in actors and q['topic_id'] in topics, 'DANGLING_REFERENCE', q['id'])
        need(actors[q['by_actor']]['role'] == 'INTERROGATOR', 'WRONG_INTERROGATOR', q['id'])
        need(actors[q['to_actor']]['role'] in ['ASSISTANT_RESPONDER', 'HUMAN_OWNER'], 'WRONG_RESPONDENT', q['id'])
        if doc['mode'] == 'SINGLE_ASSISTANT_USER_INTERVIEW':
            need(actors[q['to_actor']]['role'] == 'HUMAN_OWNER', 'WRONG_RESPONDENT', q['id'])
        if a is None:
            need(i == len(doc['exchanges']) - 1, 'ADVANCED_WITHOUT_ANSWER', q['id'])
            need(assessment is None and exchange['answer_receipt'] is None, 'ASSESSMENT_BEFORE_ANSWER', q['id'])
            pending.append(q['id'])
        else:
            need(a['by_actor'] == q['to_actor'] and a['question_id'] == q['id'], 'WRONG_RESPONDENT', q['id'])
            need(actors[a['by_actor']]['role'] in ['ASSISTANT_RESPONDER', 'HUMAN_OWNER'], 'WRONG_RESPONDENT', q['id'])
            source_refs(a['source_ids'])
            if a['classification'] == 'USER_DECISION':
                quote = a['authoritative_quote']
                need(quote and any(sources[s]['kind'] == 'HUMAN' and quote in sources[s]['verbatim_or_observation'] for s in a['source_ids']), 'HUMAN_AUTHORITY_MISSING', q['id'])
            if assessment is None:
                need(i == len(doc['exchanges']) - 1, 'ADVANCED_WITHOUT_ASSESSMENT', q['id'])
                need(not closed, 'UNASSESSED', q['id'])
            else:
                if assessment['verdict'] == 'ANSWERED':
                    need(not assessment['remaining_gaps'], 'UNRESOLVED_ANSWER', q['id'])
                    allowed = ['FACT', 'CONSTRAINT', 'USER_DECISION'] if q['answer_kind'] == 'EVIDENCE' else ['USER_DECISION'] if q['answer_kind'] == 'HUMAN_DECISION' else ['FACT', 'CONSTRAINT', 'USER_DECISION', 'INFERENCE', 'HYPOTHESIS']
                    need(a['classification'] in allowed and a['source_ids'], 'UNSUPPORTED_CLOSURE', q['id'])
                elif assessment['resolved_by'] is not None:
                    later = assessment['resolved_by']
                    need(later in question_index and question_index[later] > i, 'INVALID_RESOLUTION', q['id'])
                    successor = doc['exchanges'][question_index[later]]
                    need(successor['question']['topic_id'] == q['topic_id'] and successor['question']['dimension'] == q['dimension'] and successor['assessment'] and successor['assessment']['verdict'] == 'ANSWERED', 'INVALID_RESOLUTION', q['id'])
                else:
                    need(not closed, 'UNRESOLVED_ANSWER', q['id'])
            need(exchange['answer_receipt'] is not None, 'RECEIPT_MISSING', q['id'])
        if source is not None:
            receipt(base, exchange['question_receipt'], q['text'], source=source)
            if a is not None:
                receipt(base, exchange['answer_receipt'], a['text'], source=source)
    need(not closed or not pending, 'UNANSWERED', pending)
    if pending:
        need(doc['active_question_id'] == pending[0], 'ACTIVE_QUESTION_MISMATCH', pending)
    else:
        need(doc['active_question_id'] is None, 'ACTIVE_QUESTION_MISMATCH', doc['active_question_id'])
    if doc['status'] in ['WAITING_USER', 'WAITING_ASSISTANT']:
        need(len(pending) == 1, 'WAIT_STATE_MISMATCH', 'No single pending question')
        target = actors[questions[-1]['to_actor']]['role']
        need((doc['status'] == 'WAITING_USER') == (target == 'HUMAN_OWNER'), 'WAIT_STATE_MISMATCH', target)
    for topic in doc['topics']:
        need(topic['applicable'] == (topic['status'] != 'NOT_APPLICABLE'), 'APPLICABILITY_STATUS_MISMATCH', topic['id'])
        source_refs(topic['source_ids'])
        need(set(topic['question_ids']) <= set(question_index), 'DANGLING_REFERENCE', topic['id'])
        need(all(questions[question_index[q]]['topic_id'] == topic['id'] for q in topic['question_ids']), 'TOPIC_MISMATCH', topic['id'])
        if closed and topic['material'] and topic['applicable']:
            need(topic['status'] == 'COVERED', 'UNCOVERED_MATERIAL_TOPIC', topic['id'])
        if topic['status'] in ['COVERED', 'NOT_APPLICABLE']:
            need(topic['question_ids'] or topic['source_ids'], 'COVERAGE_WITHOUT_EVIDENCE', topic['id'])
        if topic['status'] == 'NOT_APPLICABLE':
            need(not topic['applicable'] and topic['source_ids'], 'COVERAGE_WITHOUT_EVIDENCE', topic['id'])
            if topic['material']:
                need(any(sources[s]['kind'] == 'HUMAN' for s in topic['source_ids']), 'HUMAN_AUTHORITY_MISSING', topic['id'])
        if closed and topic['status'] == 'COVERED':
            for qid in topic['question_ids']:
                e = doc['exchanges'][question_index[qid]]
                need(e['answer'] is not None and e['assessment'] is not None, 'COVERAGE_WITHOUT_EVIDENCE', topic['id'])
    kinds = []
    for event in doc['research']:
        source_refs(event['source_ids'])
        if event['kind'] in ['WEB_SEARCH', 'WEB_OPEN']:
            need('SKILL_DISCOVERY' in kinds and 'SKILL_READ' in kinds and 'MCP_DISCOVERY' in kinds, 'RESEARCH_ORDER', event['id'])
        if event['kind'] == 'MCP_QUERY':
            need('MCP_DISCOVERY' in kinds, 'RESEARCH_ORDER', event['id'])
        if event['kind'] == 'WEB_OPEN' and event['status'] == 'OK':
            need(any(sources[s]['kind'] == 'WEB_PRIMARY' for s in event['source_ids']), 'RESEARCH_INCOMPLETE', 'Web read lacks primary source binding')
        if source is not None:
            raw = _receipt_bytes(source, event['receipt_locator'], 'RESEARCH_RECEIPT_MISSING', event['id'])
            need(hashlib.sha256(raw).hexdigest() == event['receipt_sha256'], 'RESEARCH_RECEIPT_MISMATCH', event['id'])
        if event['status'] == 'OK':
            kinds.append(event['kind'])
    if closed:
        need({'SKILL_DISCOVERY', 'SKILL_READ', 'MCP_DISCOVERY', 'MCP_QUERY', 'WEB_SEARCH', 'WEB_OPEN'} <= set(kinds), 'RESEARCH_INCOMPLETE', kinds)
        need(any(s['kind'] == 'WEB_PRIMARY' for s in sources.values()), 'RESEARCH_INCOMPLETE', 'No primary web source')
    return {'status': doc['status'], 'questions': len(questions), 'pending': pending, 'semantic_validation': 'PASS_WITHIN_DECLARED_RECORD', 'receipt_files_checked': source is not None}

def validate_design(doc, interview, requirement_ids=()):
    structural(doc, 'design-proposals.schema.json')
    need(doc['project'] == interview['project'], 'PROJECT_MISMATCH', 'Design and interview projects differ')
    sources = {s['id']: s for s in interview['sources']}
    topics = {t['id'] for t in interview['topics']} | set(requirement_ids)
    unique(doc['proposals'])
    need(set(doc['source_ids']) <= set(sources), 'DANGLING_REFERENCE', 'design sources')
    if doc['status'] == 'REVIEWED' and not doc['proposals']:
        need(doc['no_change_reason'] and doc['source_ids'], 'EMPTY_DESIGN_REVIEW', 'No proposals or evidence-backed reason')
    for p in doc['proposals']:
        unique(p['alternatives'])
        need(set(p['requirement_or_topic_ids']) <= topics, 'DANGLING_REFERENCE', p['id'])
        ids = p['decision_source_ids'] + [s for alternative in p['alternatives'] for s in alternative['source_ids']]
        need(set(ids) <= set(sources), 'DANGLING_REFERENCE', p['id'])
        if p['status'] in ['ACCEPTED', 'REJECTED']:
            need(any(sources[s]['kind'] == 'HUMAN' for s in p['decision_source_ids']), 'HUMAN_AUTHORITY_MISSING', p['id'])
    return {'status': doc['status'], 'proposals': len(doc['proposals'])}

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('interview', type=Path)
    parser.add_argument('--design', type=Path)
    args = parser.parse_args()
    try:
        doc = json.loads(read_regular(args.interview.parent, args.interview.name).decode('utf-8'))
        result = validate(doc, args.interview.parent)
        if args.design:
            result['design'] = validate_design(json.loads(read_regular(args.design.parent, args.design.name).decode('utf-8')), doc)
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except (Invalid, OSError, ValueError, KeyError) as err:
        print(json.dumps({'status': 'INVALID', 'error': str(err)}, ensure_ascii=False))
        return 1

if __name__ == '__main__':
    raise SystemExit(main())

"""Small transport fixtures; no candidate files are executed or materialized."""
import hashlib
import io
import json
from pathlib import Path
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))
from git_bundle import encode_bundle, read_bundle, MAGIC


def oid(raw):
    return hashlib.sha256(b'blob ' + str(len(raw)).encode() + b'\0' + raw).hexdigest()


class BundleTests(unittest.TestCase):
    def test_binary_round_trip_and_nested_path(self):
        files = {'docs/prd.json': b'{}', 'docs/raw.txt': b'\0\xff\r\n'}
        oids = {p: oid(v) for p, v in files.items()}
        payload = encode_bundle('docs/prd.json', files, oids)
        prd, actual, hashes = read_bundle(io.BytesIO(payload))
        self.assertEqual(prd, 'docs/prd.json')
        self.assertEqual(actual, files)
        self.assertEqual(hashes, oids)

    def test_changed_blob_bytes_rejected(self):
        payload = encode_bundle('prd.json', {'prd.json': b'{}'}, {'prd.json': oid(b'{}')})
        with self.assertRaisesRegex(ValueError, 'BLOB_OID_MISMATCH'):
            read_bundle(io.BytesIO(payload[:-1] + b'x'))

    def test_truncation_and_trailing_data_rejected(self):
        payload = encode_bundle('prd.json', {'prd.json': b'{}'}, {'prd.json': oid(b'{}')})
        for bad in [payload[:-1], payload + b'x']:
            with self.subTest(size=len(bad)), self.assertRaises(ValueError):
                read_bundle(io.BytesIO(bad))

    def test_unsafe_path_and_missing_prd_rejected(self):
        for prd in ['../prd.json', '/prd.json', 'a//prd.json', 'missing.json']:
            with self.subTest(prd=prd), self.assertRaises(ValueError):
                encode_bundle(prd, {'prd.json': b'{}'}, {'prd.json': oid(b'{}')})

    def test_invalid_metadata_rejected_before_body_read(self):
        row = {'path': 'prd.json', 'oid': oid(b'{}'), 'size': 8*1024*1024+1}
        for header in [
            {'version': 1, 'prd': 'prd.json', 'files': [row]},
            {'version': True, 'prd': 'prd.json', 'files': []},
            {'version': 1, 'prd': 'prd.json', 'files': [dict(row, size=0), dict(row, size=0)]},
        ]:
            raw = json.dumps(header).encode()
            with self.assertRaises(ValueError):
                read_bundle(io.BytesIO(MAGIC + len(raw).to_bytes(4, 'big') + raw))


if __name__ == '__main__':
    unittest.main()

